 "content": "def transform(grid):
    out = [row[:] for row in grid]
    if not grid:
        return out
    # The colored pattern on the top edge supplies one vertical starting ray
    # per color. A matching marker elsewhere bends that ray along its row.
    seeds = [(c, color) for c, color in enumerate(grid[0]) if color != 0]
    for c, color in seeds:
        markers = [(r, cc) for r, row in enumerate(grid[1:], 1)
                   for cc, value in enumerate(row) if value == color]
        if markers:
            r, cc = markers[0]
        else:
            r, cc = len(grid) - 1, c
        for rr in range(min(r, len(grid) - 1) + 1):
            if out[rr][c] == 0:
                out[rr][c] = color
        step = 1 if cc >= c else -1
        for x in range(c, cc + step, step):
            if out[r][x] == 0:
                out[r][x] = color
    return out
